const options = commander.opts();

if (options.scopes && options.packages) {
    console.error('Please specify either scopes or packages, not both.');
    commander.help();
}

if (options.strategy !== 'highest' && options.strategy !== 'fewer') {
    console.error(`Invalid strategy ${options.strategy}`);
    commander.help();
}

const file = commander.args.length ? commander.args[0] : 'yarn.lock';

try {
    const yarnLock = fs.readFileSync(file, 'utf8');
    const useMostCommon = options.strategy === 'fewer';

    if (options.list) {
        const duplicates = listDuplicates(yarnLock, {
            useMostCommon,
            includeScopes: options.scopes,
            includePackages: options.packages,
            excludePackages: options.exclude,
        });
        duplicates.forEach((logLine) => console.log(logLine));
        if (options.fail && duplicates.length > 0) {
            process.exit(1);
        }
    } else {
        let dedupedYarnLock = fixDuplicates(yarnLock, {
            useMostCommon,
            includeScopes: options.scopes,
            includePackages: options.packages,
            excludePackages: options.exclude,
        });

        if (options.print) {
            console.log(dedupedYarnLock);
        } else {
            const eolMatch = yarnLock.match(/(\r?\n)/);
            if (eolMatch && eolMatch[0] === '\r\n') {
                dedupedYarnLock = dedupedYarnLock.replace(/\n/g, '\r\n');
            }
            fs.writeFileSync(file, dedupedYarnLock);
        }

        if (options.fail && yarnLock !== dedupedYarnLock) {
            process.exit(1);
        }
    }

